734	// VoteResult 是投票处理结果。
735	type VoteResult struct {
736		// Counted 本次投票是否新计入票数（重复投同一候选为 false）。
737		Counted bool
738		// Confirmed 本次投票是否令某候选立即确认。
739		Confirmed bool
740		// Block 确认时为新区块；否则为 nil。
741		Block *Block
742	}
743	
744	// Vote 处理验证者对当前轮次某已登记候选的投票。
745	// 每位验证者一轮内只能选择一个候选：重复投同一候选不增加票数但不报错；
746	// 改投其他候选明确拒绝（ReasonAlreadyVoted），原票保留。
747	// 票数严格超过名单人数三分之二时立即确认该候选，其他候选落选并进入下一轮。
748	// 名单外身份、错误轮次、未知区块标识返回带具体 Reason 的 *RejectError。
749	func (n *Node) Vote(validator []byte, round uint64, blockID string) (*VoteResult, error) {
750		n.mu.Lock()
751		defer n.mu.Unlock()
752	
753		key := fmt.Sprintf("%x", validator)
754		allowed := false
755		for _, v := range n.st.Validators {
756			if fmt.Sprintf("%x", v) == key {
757				allowed = true
758				break
759			}
760		}
761		if !allowed {
762			return nil, reject(ReasonNotValidator, "validator %s is not in the validator set", key)
763		}
764		rs := n.st.currentRoundState()
765		// 轮次优先判定：旧轮次投票不能影响新轮次，即使新轮次尚未产生本地提议。
766		if rs == nil || rs.LocalBlockID == "" {
767			if round != n.st.Round {
768				return nil, reject(ReasonWrongRound, "vote round %d does not match current round %d", round, n.st.Round)
769			}
770			return nil, reject(ReasonNoProposal, "round %d has no proposal", n.st.Round)
771		}
772		if round != rs.Round {
773			return nil, reject(ReasonWrongRound, "vote round %d does not match current round %d", round, rs.Round)
774		}
775		if _, ok := rs.Candidates[blockID]; !ok {
776			return nil, reject(ReasonWrongBlock, "block id %s is not a registered candidate in round %d", blockID, rs.Round)
777		}
778	
779		// 每位验证者一轮内只能选择一个候选。
780		for id, cand := range rs.Candidates {
781			for _, vk := range cand.Votes {
782				if vk == key {
783					if id == blockID {
784						return &VoteResult{Counted: false}, nil // 重复投同一候选不增票
785					}
786					return nil, reject(ReasonAlreadyVoted,
787						"validator %s already voted for candidate %s in round %d and cannot switch to %s", key, id, rs.Round, blockID)
788				}
789			}
790		}
791	
792		st := n.st.clone()
793		rs2 := st.Rounds[st.Round]
794		cand := rs2.Candidates[blockID]
795		cand.Votes = append(cand.Votes, key)
796		sort.Strings(cand.Votes)
797	
798		res := &VoteResult{Counted: true}
799		threshold := len(st.Validators) * 2 / 3
800		if len(cand.Votes) > threshold {
801			block := st.resolveRound(cand.BlockID, true)
802			res.Confirmed = true
803			res.Block = &block
804		}
805		if err := n.save(st); err != nil {
806			return nil, err
807		}
808		n.st = st
809		return res, nil
810	}
811	
812	// resolveRound 在内存状态上完整应用一轮的决出：
813	// confirm 为 true 时胜出候选按其交易顺序生成连续高度的确认块，随后胜出与落选
814	// 候选中引用的交易分别按规则处理（确认一次 / 回到排队），最后进入下一轮并使
815	// 到期交易失效。confirm 为 false（EndRound）时不生成确认块，所有候选引用的
816	// 交易全部回到排队。调用方随后通过一次原子保存落盘。
817	func (s *state) resolveRound(winnerID string, confirm bool) Block {
818		rs := s.Rounds[s.Round]
819		var block Block
820		winnerTx := map[string]struct{}{}
821		if confirm {
822			winner := rs.Candidates[winnerID]
823			height := uint64(len(s.Blocks)) + 1
824			block = Block{
825				Height:     height,
826				Round:      rs.Round,
827				ID:         winner.BlockID,
828				PreviousID: s.LastBlock,
829				TxIDs:      append([]string(nil), winner.TxIDs...),
830			}
831			if block.TxIDs == nil {
832				block.TxIDs = []string{}
833			}
834			for _, id := range block.TxIDs {
835				winnerTx[id] = struct{}{}
836				e := s.Entries[id]
837				sender := e.Tx.SenderHex()
838				// 候选校验保证序号从已确认序号加一起连续递增。
839				s.Accounts[sender] = e.Tx.Sequence
840				delete(s.Pool[sender], e.Tx.Sequence)
841				if len(s.Pool[sender]) == 0 {
842					delete(s.Pool, sender)
843				}
844				e.Status = stConfirmed
845				e.ReplacedBy = ""
846				s.Confirmed[id] = confirmedRef{Height: height, Block: block.ID}
847			}
848			s.Blocks = append(s.Blocks, block)
849			s.LastBlock = block.ID
850		}
851		// 标记全部候选的胜出/落选结果；只有未在胜出块中的交易才回到排队。
852		// 被多个候选共享的胜出交易只确认一次，落选候选不能再改变其状态。
853		for id, cand := range rs.Candidates {
854			cand.Decided = true
855			cand.Winner = confirm && id == winnerID
856			if !cand.Winner {
857				for _, txID := range cand.TxIDs {
858					if _, won := winnerTx[txID]; won {
859						continue
860					}
861					if e, ok := s.Entries[txID]; ok && e.Status == stProposed {
862						e.Status = stQueued
863					}
864				}
865			}
866		}
867		rs.Ended = true
868		rs.EndedByConfirm = confirm
869		s.Round++
870		s.expire()
871		return block
872	}
873	
874	// expire 使池内到期轮次不大于当前轮次的交易失效。轮次已决出，池中剩余的
875	// 均为排队交易（落选候选独有或从未被引用）。
876	func (s *state) expire() {
877		for sender, seqs := range s.Pool {
878			for seq, id := range seqs {
879				e := s.Entries[id]
880				if e.Tx.Expiry <= s.Round {
881					e.Status = stExpired
882					delete(seqs, seq)
883				}
884			}
885			if len(seqs) == 0 {
886				delete(s.Pool, sender)
887			}
888		}
889	}
890	
891	// EndRound 主动结束当前未确认轮次：所有候选落选且不生成确认块，
892	// 候选中的交易按落选规则回到排队状态，随后进入下一轮并使到期交易失效。
893	// 旧轮次投票随候选结果一并保留在历史中，但不能影响新轮次。
894	func (n *Node) EndRound() (uint64, error) {
895		n.mu.Lock()
896		defer n.mu.Unlock()
897		st := n.st.clone()
898		rs := st.Rounds[st.Round]
899		if rs == nil {
900			// 本轮尚未产生本地提议：仍允许直接结束，空轮留作未确认结束记录。
901			rs = &roundState{
902				Round:      st.Round,
903				Height:     uint64(len(st.Blocks)) + 1,
904				PreviousID: st.LastBlock,
905				Candidates: map[string]*candidateState{},
906			}
907			st.Rounds[st.Round] = rs
908		}
909		st.resolveRound("", false)
910		if err := n.save(st); err != nil {
911			return 0, err
912		}
913		n.st = st
914		return st.Round, nil
915	}
916	
917	// Height 返回已确认区块数（最新高度）。
918	func (n *Node) Height() uint64 {
919		n.mu.Lock()
920		defer n.mu.Unlock()
921		return uint64(len(n.st.Blocks))
922	}
923	
924	// BlockAt 按连续高度查询确认块，高度从 1 开始。
925	func (n *Node) BlockAt(height uint64) (Block, error) {
926		n.mu.Lock()
927		defer n.mu.Unlock()
928		if height == 0 || height > uint64(len(n.st.Blocks)) {
929			return Block{}, reject(ReasonUnknownBlock, "block at height %d does not exist", height)
930		}
931		return n.st.Blocks[height-1], nil
932	}
933	
934	// LatestBlock 返回最新确认块；尚无确认块时第二返回值为 false。
935	func (n *Node) LatestBlock() (Block, bool) {
936		n.mu.Lock()
937		defer n.mu.Unlock()
938		if len(n.st.Blocks) == 0 {
939			return Block{}, false
940		}
941		return n.st.Blocks[len(n.st.Blocks)-1], true
942	}
943	
944	// 候选结果取值。
945	const (
946		// CandidatePending 候选尚未决出，仍可接受投票。
947		CandidatePending = "pending"
948		// CandidateWon 候选胜出，其交易已确认。
949		CandidateWon = "won"
950		// CandidateLost 轮次已结束且该候选落选。
951		CandidateLost = "lost"
952	)
953	
954	// RoundCandidates 是某一轮候选情况的只读视图。返回内容均为副本，
955	// 调用方修改切片或字节不会影响节点内部状态。
956	type RoundCandidates struct {
957		// Round 查询的轮次。
958		Round uint64
959		// Candidates 本轮全部候选，按区块标识字典序排列。
960		Candidates []CandidateView
961		// Unvoted 本轮尚未投票的验证者公钥，按公钥字典序排列。
962		Unvoted [][]byte
963		// Ended 本轮是否已经决出（确认或主动结束）。
964		Ended bool
965		// UnconfirmedEnd 为 true 表示本轮由 EndRound 主动结束、未产生确认块。
966		UnconfirmedEnd bool
967		// HasRecords 为 false 表示旧版本状态未保存该轮候选详情；
968		// 此时 Candidates 为空且不代表“该轮没有候选”。
969		HasRecords bool
970	}
971	
972	// Candidates 按轮次查看候选：列出每个候选的交易顺序、投票者（按公钥排序）
973	// 及未决/胜出/落选结果，并列出本轮尚未投票的验证者。旧轮记录保留可查；
974	// 轮次为 0 或尚未到达时返回 ReasonUnknownRound。
975	//
976	// 候选按区块标识排序，身份按公钥排序。主动结束的轮次 UnconfirmedEnd 为 true。
977	// 过去没有保存候选详情的旧轮 HasRecords 为 false。
978	func (n *Node) Candidates(round uint64) (*RoundCandidates, error) {
979		n.mu.Lock()
980		defer n.mu.Unlock()
981		// 轮次 0、尚未到达的未来轮次以及尚未产生本地提议的当前轮次均无记录。
982		// 历史轮次（含旧版本迁移轮）与未决当前轮一定有条目。
983		rs := n.st.Rounds[round]
984		if round == 0 || rs == nil {
985			return nil, reject(ReasonUnknownRound, "round %d does not exist (current round %d)", round, n.st.Round)
986		}
987		view := &RoundCandidates{
988			Round:          round,
989			Candidates:     []CandidateView{},
990			Unvoted:        [][]byte{},
991			Ended:          rs.Ended,
992			UnconfirmedEnd: rs.Ended && !rs.EndedByConfirm,
993			HasRecords:     !rs.DetailMissing,
994		}
995		if !rs.DetailMissing {
996			ids := make([]string, 0, len(rs.Candidates))
997			for id := range rs.Candidates {
998				ids = append(ids, id)
999			}
1000			sort.Strings(ids)
1001			voted := map[string]struct{}{}
1002			for _, id := range ids {
1003				c := rs.Candidates[id]
1004				voters := make([][]byte, 0, len(c.Votes))
1005				for _, vk := range c.Votes {
1006					pub, err := hexDecode(vk)
1007					if err != nil {
1008						return nil, fmt.Errorf("corrupt voter key %q: %w", vk, err)
1009					}
1010					voters = append(voters, pub)
1011					voted[vk] = struct{}{}
1012				}
1013				result := CandidatePending
1014				if c.Decided {
1015					if c.Winner {
1016						result = CandidateWon
1017					} else {
1018						result = CandidateLost
1019					}
1020				}
1021				view.Candidates = append(view.Candidates, CandidateView{
1022					Round:   rs.Round,
1023					BlockID: c.BlockID,
1024					TxIDs:   append([]string(nil), c.TxIDs...),
1025					Local:   c.Local,
1026					Voters:  voters,
1027					Result:  result,
1028				})
1029			}
1030			valKeys := make([]string, 0, len(n.st.Validators))
1031			for _, v := range n.st.Validators {
1032				k := fmt.Sprintf("%x", v)
1033				if _, ok := voted[k]; !ok {
1034					valKeys = append(valKeys, k)
1035				}
1036			}
1037			sort.Strings(valKeys)
1038			for _, k := range valKeys {
1039				pub, err := hexDecode(k)
1040				if err != nil {
1041					return nil, fmt.Errorf("corrupt validator key %q: %w", k, err)
1042				}
1043				view.Unvoted = append(view.Unvoted, pub)
1044			}
1045		}
1046		return view, nil
1047	}
1048	
1049	// hexDecode 解码十六进制公钥，非法输入返回错误。
1050	func hexDecode(h string) ([]byte, error) {
1051		return hex.DecodeString(h)
1052	}
1053	
1054	// Tx 按交易标识查询其状态并关联区块或替代交易。
1055	func (n *Node) Tx(id string) (*TxInfo, error) {
1056		n.mu.Lock()
1057		defer n.mu.Unlock()
1058		if e, ok := n.st.Entries[id]; ok {
1059			info := &TxInfo{
1060				ID:         id,
1061				Status:     TxStatus(e.Status),
1062				Tx:         copyTx(e.Tx),
1063				ReplacedBy: e.ReplacedBy,
1064			}
1065			if e.Status == stConfirmed {
1066				if ref, ok := n.st.Confirmed[id]; ok {
1067					info.BlockHeight = ref.Height
1068					info.BlockID = ref.Block
1069				}
1070			}
1071			if e.Status == stDropped {
1072				info.DropReason = e.DropReason
1073				info.DropRound = e.DropRound
1074			}
1075			return info, nil
1076		}
1077		return nil, reject(ReasonUnknownTx, "transaction %s not found", id)
1078	}
1079	
1080	// Account 按发送者公钥查询已确认序号与全部待处理交易。
1081	// 因序号缺口等待时 Gap 给出最早缺少的序号；
1082	// 已提议交易显示等待投票，其余池内交易显示等待打包。
1083	func (n *Node) Account(sender []byte) *AccountInfo {
1084		n.mu.Lock()
1085		defer n.mu.Unlock()
1086		key := fmt.Sprintf("%x", sender)
1087		info := &AccountInfo{
1088			Sender:            key,
1089			ConfirmedSequence: n.st.Accounts[key],
1090			Pending:           []*TxInfo{},
1091		}
1092		seqs := n.st.Pool[key]
1093		if len(seqs) == 0 {
1094			return info
1095		}
1096		seqList := make([]uint64, 0, len(seqs))
1097		for seq := range seqs {
1098			seqList = append(seqList, seq)
1099		}
1100		sort.Slice(seqList, func(i, j int) bool { return seqList[i] < seqList[j] })
1101		expected := info.ConfirmedSequence + 1
1102		var gap uint64
1103		for _, seq := range seqList {
1104			if gap == 0 {
1105				if seq == expected {
1106					expected++
1107				} else if seq > expected {
1108					gap = expected
1109				}
1110			}
1111			id := seqs[seq]
1112			e := n.st.Entries[id]
1113			txInfo := &TxInfo{
1114				ID:     id,
1115				Status: TxStatus(e.Status),
1116				Tx:     copyTx(e.Tx),
1117			}
1118			if e.Status == stProposed {
1119				txInfo.Note = "waiting-vote"
1120			} else {
1121				txInfo.Note = "waiting-pack"
1122			}
1123			info.Pending = append(info.Pending, txInfo)
1124		}
1125		info.Gap = gap
1126		return info
1127	}
1128	
1129	func copyTx(tx *Transaction) *Transaction {
1130		if tx == nil {
1131			return nil
1132		}
1133		c := *tx
1134		c.Sender = append([]byte(nil), tx.Sender...)
1135		c.Content = append([]byte(nil), tx.Content...)
1136		c.Signature = append([]byte(nil), tx.Signature...)
1137		return &c
1138	}
1139

