1	package consensus
2	
3	import (
4		"crypto/ed25519"
5		"crypto/rand"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"testing"
11	)
12	
13	type testKey struct {
14		priv ed25519.PrivateKey
15		pub  ed25519.PublicKey
16	}
17	
18	func genKeys(t *testing.T, n int) []testKey {
19		t.Helper()
20		keys := make([]testKey, n)
21		for i := range keys {
22			pub, priv, err := ed25519.GenerateKey(rand.Reader)
23			if err != nil {
24				t.Fatal(err)
25			}
26			keys[i] = testKey{priv: priv, pub: pub}
27		}
28		return keys
29	}
30	
31	func newTestNode(t *testing.T, keys []testKey, maxTxs uint64) (*Node, string) {
32		t.Helper()
33		dir := t.TempDir()
34		vals := make([][]byte, len(keys))
35		for i, k := range keys {
36			vals[i] = k.pub
37		}
38		n, err := New(dir, Config{Seed: []byte("test-seed-v1"), Validators: vals, MaxTxsPerBlock: maxTxs})
39		if err != nil {
40			t.Fatal(err)
41		}
42		return n, dir
43	}
44	
45	func reason(err error) string {
46		var re *RejectError
47		if errors.As(err, &re) {
48			return re.Reason
49		}
50		return ""
51	}
52	
53	// 初始状态：轮次 1，账户确认序号 0，配置必须校验。
54	func TestInitialState(t *testing.T) {
55		keys := genKeys(t, 4)
56		n, _ := newTestNode(t, keys, 10)
57		if n.CurrentRound() != 1 {
58			t.Fatalf("initial round = %d, want 1", n.CurrentRound())
59		}
60		if n.Height() != 0 {
61			t.Fatalf("initial height = %d, want 0", n.Height())
62		}
63		acct := n.Account(keys[0].pub)
64		if acct.ConfirmedSequence != 0 {
65			t.Fatalf("initial confirmed seq = %d, want 0", acct.ConfirmedSequence)
66		}
67		if acct.Gap != 0 || len(acct.Pending) != 0 {
68			t.Fatalf("unexpected pending: %+v", acct)
69		}
70	
71		dir := t.TempDir()
72		cfg := Config{Seed: []byte("s"), Validators: [][]byte{keys[0].pub}, MaxTxsPerBlock: 1}
73		if _, err := New(dir, Config{Validators: cfg.Validators, MaxTxsPerBlock: 1}); err == nil {
74			t.Fatal("empty seed should be rejected")
75		}
76		if _, err := New(t.TempDir(), Config{Seed: []byte("s"), MaxTxsPerBlock: 1}); err == nil {
77			t.Fatal("empty validators should be rejected")
78		}
79		if _, err := New(t.TempDir(), Config{Seed: []byte("s"), Validators: cfg.Validators, MaxTxsPerBlock: 0}); err == nil {
80			t.Fatal("zero max txs should be rejected")
81		}
82		if _, err := New(t.TempDir(), Config{Seed: []byte("s"), Validators: [][]byte{keys[0].pub, keys[0].pub}, MaxTxsPerBlock: 1}); err == nil {
83			t.Fatal("duplicate validators should be rejected")
84		}
85	}
86	
87	// 签名编码与交易标识稳定。
88	func TestStableEncoding(t *testing.T) {
89		keys := genKeys(t, 1)
90		tx := NewTransaction(keys[0].priv, 7, []byte("hello"), 3, 99)
91		id1, sb1 := tx.ID(), tx.SigningBytes()
92		// 重新逐字节构造一份相同内容的交易，标识与签名编码必须一致。
93		tx2 := NewTransaction(keys[0].priv, 7, []byte("hello"), 3, 99)
94		if tx2.ID() != id1 {
95			t.Fatal("same bytes must yield same id")
96		}
97		if string(tx2.SigningBytes()) != string(sb1) {
98			t.Fatal("signing bytes must be stable")
99		}
100		if !tx2.Verify() {
101			t.Fatal("valid signature should verify")
102		}
103		// 篡改内容后签名失效。
104		tx2.Content = []byte("tampered")
105		if tx2.Verify() {
106			t.Fatal("tampered content must fail verification")
107		}
108		// 签名必须覆盖费用、到期轮次与序号。
109		txFee := NewTransaction(keys[0].priv, 7, []byte("hello"), 3, 99)
110		txFee.Fee++
111		if txFee.Verify() {
112			t.Fatal("tampered fee must fail verification")
113		}
114		txExp := NewTransaction(keys[0].priv, 7, []byte("hello"), 3, 99)
115		txExp.Expiry++
116		if txExp.Verify() {
117			t.Fatal("tampered expiry must fail verification")
118		}
119		txSeq := NewTransaction(keys[0].priv, 7, []byte("hello"), 3, 99)
120		txSeq.Sequence++
121		if txSeq.Verify() {
122			t.Fatal("tampered sequence must fail verification")
123		}
124		// 不同费用产生不同标识。
125		tx3 := NewTransaction(keys[0].priv, 7, []byte("hello"), 4, 99)
126		if tx3.ID() == id1 {
127			t.Fatal("different fee must yield different id")
128		}
129	}
130	
131	// 各种拒绝原因。
132	func TestSubmitRejections(t *testing.T) {
133		keys := genKeys(t, 4)
134		n, _ := newTestNode(t, keys, 10)
135	
136		// 非法签名
137		bad := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 10)
138		bad.Signature[0] ^= 0xff
139		if _, err := n.Submit(bad); reason(err) != ReasonBadSignature {
140			t.Fatalf("got %v, want %s", err, ReasonBadSignature)
141		}
142	
143		// 序号非正
144		zero := NewTransaction(keys[0].priv, 0, []byte("a"), 1, 10)
145		if _, err := n.Submit(zero); reason(err) != "sequence-must-be-positive" {
146			t.Fatalf("got %v, want sequence-must-be-positive", err)
147		}
148	
149		// 已到期：到期轮次不大于当前轮次 1
150		exp := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 1)
151		if _, err := n.Submit(exp); reason(err) != ReasonExpired {
152			t.Fatalf("got %v, want %s", err, ReasonExpired)
153		}
154	
155		ok := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 10)
156		res, err := n.Submit(ok)
157		if err != nil {
158			t.Fatal(err)
159		}
160	
161		// 完全相同的交易重复提交
162		if _, err := n.Submit(NewTransaction(keys[0].priv, 1, []byte("a"), 1, 10)); reason(err) != ReasonDuplicate {
163			t.Fatalf("got %v, want %s", err, ReasonDuplicate)
164		}
165	
166		// 同序号费用不更高
167		low := NewTransaction(keys[0].priv, 1, []byte("b"), 1, 10)
168		if _, err := n.Submit(low); reason(err) != ReasonLowFee {
169			t.Fatalf("got %v, want %s", err, ReasonLowFee)
170		}
171	
172		// 费用严格更高才能替换
173		hi := NewTransaction(keys[0].priv, 1, []byte("b"), 5, 10)
174		rep, err := n.Submit(hi)
175		if err != nil {
176			t.Fatal(err)
177		}
178		if rep.ReplacedID != res.TxID || rep.TxID != hi.ID() {
179			t.Fatalf("replacement result wrong: %+v", rep)
180		}
181		oldInfo, err := n.Tx(res.TxID)
182		if err != nil {
183			t.Fatal(err)
184		}
185		if oldInfo.Status != StatusReplaced || oldInfo.ReplacedBy != hi.ID() {
186			t.Fatalf("old tx status = %s replacedBy=%s, want replaced/%s", oldInfo.Status, oldInfo.ReplacedBy, hi.ID())
187		}
188		newInfo, _ := n.Tx(hi.ID())
189		if newInfo.Status != StatusQueued {
190			t.Fatalf("new tx status = %s, want queued", newInfo.Status)
191		}
192	}
193	
194	// 确认后序号不大于已确认序号被拒；缺口交易可入池等待，查询指出最早缺口。
195	func TestGapAndConfirmedSequence(t *testing.T) {
196		keys := genKeys(t, 4)
197		n, _ := newTestNode(t, keys, 10)
198	
199		tx2 := NewTransaction(keys[0].priv, 2, []byte("two"), 1, 100)
200		if _, err := n.Submit(tx2); err != nil {
201			t.Fatal(err)
202		}
203		acct := n.Account(keys[0].pub)
204		if acct.Gap != 1 || len(acct.Pending) != 1 {
205			t.Fatalf("gap = %d pending = %d, want gap 1", acct.Gap, len(acct.Pending))
206		}
207		if acct.Pending[0].Note != "waiting-pack" {
208			t.Fatalf("note = %q, want waiting-pack", acct.Pending[0].Note)
209		}
210	
211		tx1 := NewTransaction(keys[0].priv, 1, []byte("one"), 1, 100)
212		if _, err := n.Submit(tx1); err != nil {
213			t.Fatal(err)
214		}
215		acct = n.Account(keys[0].pub)
216		if acct.Gap != 0 {
217			t.Fatalf("gap = %d, want 0", acct.Gap)
218		}
219	
220		p, err := n.Propose()
221		if err != nil {
222			t.Fatal(err)
223		}
224		if len(p.TxIDs) != 2 || p.TxIDs[0] != tx1.ID() || p.TxIDs[1] != tx2.ID() {
225			t.Fatalf("block order wrong: %v", p.TxIDs)
226		}
227		confirmByVotes(t, n, keys, p.BlockID)
228		if n.CurrentRound() != 2 {
229			t.Fatalf("round = %d, want 2", n.CurrentRound())
230		}
231	
232		acct = n.Account(keys[0].pub)
233		if acct.ConfirmedSequence != 2 {
234			t.Fatalf("confirmed = %d, want 2", acct.ConfirmedSequence)
235		}
236		// 序号不大于已确认序号
237		replay := NewTransaction(keys[0].priv, 2, []byte("two"), 1, 100)
238		if _, err := n.Submit(replay); reason(err) != ReasonDuplicate {
239			t.Fatalf("same tx replay got %v, want duplicate", err)
240		}
241		oldSeq := NewTransaction(keys[0].priv, 1, []byte("one"), 9, 100)
242		if _, err := n.Submit(oldSeq); reason(err) != ReasonOldSequence {
243			t.Fatalf("got %v, want %s", err, ReasonOldSequence)
244		}
245	}
246	
247	// 打包顺序：跨账户按费用，同账户后续序号必须等前一条被选入；达到上限停止。
248	func TestPackingOrder(t *testing.T) {
249		keys := genKeys(t, 4)
250		n, _ := newTestNode(t, keys, 2)
251	
252		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 10, 100)
253		a2 := NewTransaction(keys[0].priv, 2, []byte("a2"), 100, 100) // 费用最高，但必须等 a1 选入后才可考虑
254		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 50, 100)
255		for _, tx := range []*Transaction{a1, a2, b1} {
256			if _, err := n.Submit(tx); err != nil {
257				t.Fatal(err)
258			}
259		}
260		p, err := n.Propose()
261		if err != nil {
262			t.Fatal(err)
263		}
264		// 第一次取各账户下一条：b1(50) 高于 a1(10)；第二次只有 a1 可确认，
265		// a2 因序号缺口本轮取不到，且已达上限 2。
266		want := []string{b1.ID(), a1.ID()}
267		if fmt.Sprint(p.TxIDs) != fmt.Sprint(want) {
268			t.Fatalf("packed %v, want %v", p.TxIDs, want)
269		}
270		// 确认后下一轮 a2 成为该账户下一条可确认交易并被打包
271		confirmByVotes(t, n, keys, p.BlockID)
272		p2, err := n.Propose()
273		if err != nil {
274			t.Fatal(err)
275		}
276		if len(p2.TxIDs) != 1 || p2.TxIDs[0] != a2.ID() {
277			t.Fatalf("round 2 packed %v, want [a2]", p2.TxIDs)
278		}
279	}
280	
281	// 费用相同时按交易标识字典序选择（确定性可复算）。
282	func TestTieBreakByID(t *testing.T) {
283		keys := genKeys(t, 4)
284		n, _ := newTestNode(t, keys, 1)
285		txs := make([]*Transaction, 4)
286		for i := range txs {
287			txs[i] = NewTransaction(keys[i].priv, 1, []byte("x"), 7, 100)
288			if _, err := n.Submit(txs[i]); err != nil {
289				t.Fatal(err)
290			}
291		}
292		p, err := n.Propose()
293		if err != nil {
294			t.Fatal(err)
295		}
296		minID := txs[0].ID()
297		for _, tx := range txs[1:] {
298			if tx.ID() < minID {
299				minID = tx.ID()
300			}
301		}
302		if len(p.TxIDs) != 1 || p.TxIDs[0] != minID {
303			t.Fatalf("picked %v, want lexicographically smallest %s", p.TxIDs, minID)
304		}
305	}
306	
307	// 重复请求返回同一提议；提议冻结后新交易不改变提议，提议中交易禁止替换。
308	func TestProposalStableAndFrozen(t *testing.T) {
309		keys := genKeys(t, 4)
310		n, _ := newTestNode(t, keys, 10)
311		tx1 := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 100)
312		if _, err := n.Submit(tx1); err != nil {
313			t.Fatal(err)
314		}
315		p1, err := n.Propose()
316		if err != nil {
317			t.Fatal(err)
318		}
319		p2, err := n.Propose()
320		if err != nil {
321			t.Fatal(err)
322		}
323		if p1.BlockID != p2.BlockID || len(p2.TxIDs) != 1 || p2.TxIDs[0] != tx1.ID() {
324			t.Fatal("repeated proposal must be identical")
325		}
326		// 提议后再提交的交易不改变当前提议
327		tx2 := NewTransaction(keys[1].priv, 1, []byte("b"), 99, 100)
328		if _, err := n.Submit(tx2); err != nil {
329			t.Fatal(err)
330		}
331		p3, _ := n.Propose()
332		if len(p3.TxIDs) != 1 {
333			t.Fatalf("proposal changed after new submit: %v", p3.TxIDs)
334		}
335		// 提议中的交易禁止替换
336		replace := NewTransaction(keys[0].priv, 1, []byte("a2"), 999, 100)
337		if _, err := n.Submit(replace); reason(err) != ReasonProposalLocked {
338			t.Fatalf("got %v, want %s", err, ReasonProposalLocked)
339		}
340		info, _ := n.Tx(tx1.ID())
341		if info.Status != StatusProposed {
342			t.Fatalf("tx in proposal status = %s, want proposed", info.Status)
343		}
344		acct := n.Account(keys[0].pub)
345		if len(acct.Pending) != 1 || acct.Pending[0].Status != StatusProposed || acct.Pending[0].Note != "waiting-vote" {
346			t.Fatalf("proposed tx should show waiting-vote: %+v", acct.Pending)
347		}
348		// 未确认时结束轮次，交易回到排队状态
349		r, err := n.EndRound()
350		if err != nil {
351			t.Fatal(err)
352		}
353		if r != 2 {
354			t.Fatalf("round after end = %d, want 2", r)
355		}
356		acct = n.Account(keys[0].pub)
357		if acct.Pending[0].Status != StatusQueued || acct.Pending[0].Note != "waiting-pack" {
358			t.Fatalf("returned tx should be queued/waiting-pack: %+v", acct.Pending[0])
359		}
360		if _, ok := n.Proposal(); ok {
361			t.Fatal("proposal should be cleared after EndRound")
362		}
363		if n.Height() != 0 {
364			t.Fatal("ended round must leave no confirmed block")
365		}
366	}
