368	// 空块：没有可选交易时返回空块并按相同条件确认。
369	func TestEmptyBlock(t *testing.T) {
370		keys := genKeys(t, 4)
371		n, _ := newTestNode(t, keys, 10)
372		p, err := n.Propose()
373		if err != nil {
374			t.Fatal(err)
375		}
376		if !p.Empty || len(p.TxIDs) != 0 {
377			t.Fatalf("want empty proposal, got %+v", p)
378		}
379		emptyID := p.BlockID
380		confirmByVotes(t, n, keys, p.BlockID)
381		b, err := n.BlockAt(1)
382		if err != nil {
383			t.Fatal(err)
384		}
385		if b.ID != emptyID || len(b.TxIDs) != 0 || b.Height != 1 || b.Round != 1 {
386			t.Fatalf("empty block wrong: %+v", b)
387		}
388		if b.PreviousID != "" {
389			t.Fatalf("genesis previous id = %q, want empty", b.PreviousID)
390		}
391	}
