383	// EndRound：所有候选落选不留块，交易回池；查询明确显示未确认结束。
384	func TestEndRoundAllCandidatesLost(t *testing.T) {
385		keys := genKeys(t, 4)
386		n, _ := newTestNode(t, keys, 10)
387		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 1, 100)
388		n.Submit(a1)
389		local, _ := n.Propose()
390		alt, err := n.RegisterCandidate(1, []string{}) // 空块竞争候选
391		if err != nil {
392			t.Fatal(err)
393		}
394		n.Vote(keys[0].pub, 1, local.BlockID)
395		n.Vote(keys[1].pub, 1, alt.BlockID)
396	
397		r, err := n.EndRound()
398		if err != nil || r != 2 {
399			t.Fatalf("EndRound = %d, %v", r, err)
400		}
401		rc, _ := n.Candidates(1)
402		if !rc.Ended || !rc.UnconfirmedEnd {
403			t.Fatalf("ended round should be marked unconfirmed-end: %+v", rc)
404		}
405		for _, c := range rc.Candidates {
406			if c.Result != CandidateLost {
407				t.Fatalf("candidate %s result = %s, want lost", c.BlockID, c.Result)
408			}
409		}
410		// 旧票不影响新轮次：同一名验证者可在新轮次重新选择。
411		p2, _ := n.Propose()
412		if res, err := n.Vote(keys[0].pub, 2, p2.BlockID); err != nil || !res.Counted {
413			t.Fatalf("vote in new round: %+v %v", res, err)
414		}
415		if info, _ := n.Tx(a1.ID()); info.Status != StatusProposed {
416			t.Fatalf("a1 should be proposed again in round 2: %s", info.Status)
417		}
418	}
