599	// 版本 1 的旧状态目录仍可打开：未决提议与票数作为本地候选恢复，
600	// 过去没有保存的候选详情明确显示无记录，确认块不变。
601	func TestOpenV1State(t *testing.T) {
602		keys := genKeys(t, 4)
603		dir := t.TempDir()
604		vals := make([][]byte, len(keys))
605		for i, k := range keys {
606			vals[i] = k.pub
607		}
608		n, err := New(dir, Config{Seed: []byte("v1-seed"), Validators: vals, MaxTxsPerBlock: 5})
609		if err != nil {
610			t.Fatal(err)
611		}
612		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 1, 100)
613		n.Submit(a1)
614		p, _ := n.Propose()
615		n.Vote(keys[0].pub, 1, p.BlockID)
616	
617		// 把当前状态改写为版本 1 的文件形态：仅 Proposal 字段，没有 Rounds。
618		st := n.st.clone()
619		rs := st.Rounds[1]
620		local := rs.Candidates[rs.LocalBlockID]
621		st.Version = 1
622		st.Rounds = nil
623		st.Proposal = &proposalState{
624			Round:   rs.Round,
625			TxIDs:   append([]string{}, local.TxIDs...),
626			BlockID: local.BlockID,
627			Votes:   append([]string{}, local.Votes...),
628		}
629		writeRawState(t, dir, st)
630	
631		n2, err := Open(dir)
632		if err != nil {
633			t.Fatal(err)
634		}
635		if n2.CurrentRound() != 1 {
636			t.Fatalf("round = %d, want 1", n2.CurrentRound())
637		}
638		p2, ok := n2.Proposal()
639		if !ok || p2.BlockID != p.BlockID || fmt.Sprint(p2.TxIDs) != fmt.Sprint(p.TxIDs) {
640			t.Fatalf("v1 proposal not restored as local candidate: %+v", p2)
641		}
642		rc, err := n2.Candidates(1)
643		if err != nil {
644			t.Fatal(err)
645		}
646		if !rc.HasRecords || len(rc.Candidates) != 1 || !rc.Candidates[0].Local {
647			t.Fatalf("v1 pending proposal should restore with details: %+v", rc)
648		}
649		if len(rc.Candidates[0].Voters) != 1 {
650			t.Fatal("v1 votes not restored as local candidate votes")
651		}
652		if res, _ := n2.Vote(keys[0].pub, 1, p.BlockID); res.Counted {
653			t.Fatal("restored v1 vote should dedup")
654		}
655		res, _ := n2.Vote(keys[1].pub, 1, p.BlockID)
656		res, _ = n2.Vote(keys[2].pub, 1, p.BlockID)
657		if !res.Confirmed {
658			t.Fatal("v1 node should confirm after reopening")
659		}
660	}
