	}

	n2, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	reopened, _ := n2.BlockAt(1)
	fmt.Println("reopened block txids:", reopened.TxIDs, "id:", reopened.ID)
	info, _ := n2.Tx(tx1.ID())
	fmt.Println("tx1 info:", info.Status, info.BlockHeight, info.BlockID)
	fmt.Println("original want:", want)
}

